	scwin.rowAdd_onclick = function() {
		dlList.insertRow(0);
		grdList.setCellReadOnly( 0 , "appCd" , false );
		grdList.setCellReadOnly( 0 , "appCd2" , false );



		info = { 
				inputType : "autoComplete" , 
				  options : { 
						caseSensitive: "false",
		                  viewType: "icon"
		                  ,selectedData : "false"
		                  ,chooseOption : "true" 
		                  ,chooseOptionLabel : "$blank",
						  search: "contain",
						  noResult: "clear"
		                  //,allowChar: "'a-zA-Z0-9'"
				  }, 
				  itemSet : { 
				             nodeset:"data:dlCode", 
				             label: "comCdDesc", 
				             value: "appCd" 
				  } 
			}
			grdList.setCellInputType( 0 , "appCd2" , info );

			grdList.setFocusedCell( 0 , "appCd" , true );
	};

	scwin.checkVal = function() {
		return scwin.__getDom('G_'+$p.id+'grdList___autoComplete_0_appCd2_dynamic_autoComplete_0_1_itemTable_0').innerText == 'FINANCE ACCOUNT RECEIVABLE';
	}
